message.content:
{
  "title": "The Rescue Through Ruined Splendor",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined royal city.",
      "visual_description": "A crumbling stone wall with a massive iron gate hangs crookedly. Dusty royal banners flutter in the wind. The sky is gray.",
      "characters": ["Elena", "Kael", "Maren"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn the party of dangers.",
      "visual_description": "A narrow alley with huddling figures in tattered clothes. Eyes wide, they point toward the gate.",
      "characters": ["Elena", "Kael", "Maren", "Town Elder"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march past the castle gates.",
      "visual_description": "Four soldiers in dented armor, swords drawn, patrol the main courtyard. Banners hang limp above them.",
      "characters": ["Patrol Leader", "Guard 1", "Guard 2", "Guard 3"]
    },
    {
      "scene_number": 4,
      "caption": "The party slips through a hidden side entrance.",
      "visual_description": "A cracked wall covered in ivy. Kael pushes a stone, revealing a dark passage.",
      "characters": ["Elena", "Kael", "Maren"]
    },
    {
      "scene_number": 5,
      "caption": "They face the first cursed tower.",
      "visual_description": "A spiral tower with glowing runes. Shadows writhe on the walls. A woman's ghostly wail echoes.",
      "characters": ["Elena", "Kael", "Maren"]
    },
    {
      "scene_number": 6,
      "caption": "A rumor of dragons is whispered by a captive.",
      "visual_description": "Small cell with straw. A man in chains looks up, eyes haunted, muttering about a dragon in the high tower.",
      "characters": ["Elena", "Kael", "Maren", "Captive Man"]
    },
    {
      "scene_number": 7,
      "caption": "The party opens a magic door with a riddle.",
      "visual_description": "A stone door carved with constellations. Kael speaks a riddle, the door glows and swings open.",
      "characters": ["Elena", "Kael", "Maren"]
    },
    {
      "scene_number": 8,
      "caption": "They navigate a hall of mirrors and illusions.",
      "visual_description": "Endless reflections, some showing monstrous versions of the party. Maren shatters a mirror to clear the way.",
      "characters": ["Elena", "Kael", "Maren"]
    },
    {
      "scene_number": 9,
      "caption": "Entering the throne room, they find a false king.",
      "visual_description": "A grand hall with a tattered red carpet. On the throne sits an imposter in a dragon mask, surrounded by guards.",
      "characters": ["Elena", "Kael", "Maren", "False King", "Guard 1", "Guard 2", "Guard 3"]
    },
    {
      "scene_number": 10,
      "caption": "The false king offers temptation: power for betrayal.",
      "visual_description": "Golden goblets and jewels on a table. The false king smiles, holding out a crown to Elena.",
      "characters": ["Elena", "Kael", "Maren", "False King"]
    },
    {
      "scene_number": 11,
      "caption": "Elena refuses, and a fight breaks out.",
      "visual_description": "Swords clash, magic sparks, guards charge. Kael shoves over the table, spilling treasures.",
      "characters": ["Elena", "Kael", "Maren", "False King", "Guard 1", "Guard 2", "Guard 3"]
    },
    {
      "scene_number": 12,
      "caption": "They escape into the tower where the dragon is rumored.",
      "visual_description": "A spiral staircase lit by flickering torches. Dust and cobwebs everywhere. The sound of heavy breathing above.",
      "characters": ["Elena", "Kael", "Maren"]
    },
    {
      "scene_number": 13,
      "caption": "The dragon is real but chained, and guards keep it.",
      "visual_description": "A large chamber with a copper dragon chained to a pillar. Armored guards stand ready with spears.",
      "characters": ["Elena", "Kael", "Maren", "Dragon", "Guard 1", "Guard 2"]
    },
    {
      "scene_number": 14,
      "caption": "The party frees the dragon, which helps them.",
      "visual_description": "Kael picks the lock on the chains. The dragon roars, blasts guards with fire, then bows to the party.",
      "characters": ["Elena", "Kael", "Maren", "Dragon"]
    },
    {
      "scene_number": 15,
      "caption": "They find the true captive in a secret room.",
      "visual_description": "A hidden door behind a tapestry. Inside, a princess sits by a window, unbound but guarded by a warden.",
      "characters": ["Elena", "Kael", "Maren", "Princess Lyra", "Warden"]
    },
    {
      "scene_number": 16,
      "caption": "The warden is defeated, and the princess joins them.",
      "visual_description": "The warden falls to a combined spell and sword strike. Princess Lyra picks up a fallen sword.",
      "characters": ["Elena", "Kael", "Maren", "Princess Lyra", "Warden"]
    },
    {
      "scene_number": 17,
      "caption": "They flee across the castle bridge as alarms sound.",
      "visual_description": "A stone bridge over a chasm, torches lit along the walls. Guards pour onto the bridge behind them.",
      "characters": ["Elena", "Kael", "Maren", "Princess Lyra", "Dragon", "Guard 1", "Guard 2"]
    },
    {
      "scene_number": 18,
      "caption": "The dragon carries them to safety as the city burns.",
      "visual_description": "The party clings to the dragon's back. The ruined city shrinks below, smoke rising, banners torn, and the bridge collapses.",
      "characters": ["Elena", "Kael", "Maren", "Princess Lyra", "Dragon"]
    }
  ]
}

